            action,
            name,
            method,
            beforeUpload,
            onProgress,
            onError,
            withCredentials,
            headers,
            data,
            onSuccess,
            ...others
        } = this.props;

        const props = others;

        return (
            <Selecter
                {...transform(props, () => {})}
                onSelect={this.handleSelect}
            />
        );
    }
};

Upload.List = List;

